mapper.select:
SELECT tmp.analysis_tpl_id FROM (SELECT t1.analysis_tpl_id, MAX(`visit_begin_time`) AS visit_begin_time FROM ssm_analysis_tpl_visit_log t1 INNER JOIN ssm_analysis_tpl_base t2 ON t1.analysis_tpl_id = t2.analysis_tpl_id WHERE t1.visit_begin_time >= DATE_SUB(CURDATE(), INTERVAL 7 DAY) AND t1.user_name = #{userName} AND (t1.visit_type IS NULL OR t1.visit_type = 'analysis_template') AND t2.is_active = 1
AND t2.analysis_tpl_type = #{analysisTplType}
GROUP BY analysis_tpl_id) tmp ORDER BY tmp.visit_begin_time DESC
